<script setup lang="ts">
import { ref, onMounted, onBeforeUnmount, watch, nextTick } from 'vue';
const props = withDefaults(defineProps<{ images: string[]; start?: number; label: string }>(), { start:0 });
const emit = defineEmits<{ close: [] }>();
const root = ref<HTMLElement>(); const track = ref<HTMLElement>(); const index = ref(props.start); let previous: HTMLElement | null = null;
function move(to: number) { index.value = Math.max(0,Math.min(props.images.length-1,to)); track.value?.scrollTo?.({left:index.value*track.value.clientWidth,behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth'}); }
function keys(e: KeyboardEvent) { if(e.key==='Escape') emit('close'); if(e.key==='ArrowRight') move(index.value+1); if(e.key==='ArrowLeft') move(index.value-1); if(e.key==='Tab') { const buttons = Array.from(root.value?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)') ?? []); if(!buttons.length)return; const first=buttons[0]!,last=buttons[buttons.length-1]!; if(e.shiftKey && document.activeElement===first){e.preventDefault();last.focus();} else if(!e.shiftKey && document.activeElement===last){e.preventDefault();first.focus();} } }
onMounted(async()=>{ document.addEventListener('keydown', keys); previous=document.activeElement as HTMLElement; await nextTick(); root.value?.querySelector<HTMLButtonElement>('button')?.focus(); move(props.start); });
onBeforeUnmount(()=>{document.removeEventListener('keydown', keys);previous?.focus();}); watch(()=>props.images,()=>move(0));
</script>
<template><Teleport to="body"><section ref="root" class="image-carousel" role="dialog" aria-modal="true" :aria-label="label"><button class="close" aria-label="关闭图片预览" @click="emit('close')">×</button><div ref="track" class="carousel-track" @scroll="index = Math.round(($event.target as HTMLElement).scrollLeft / Math.max(1,($event.target as HTMLElement).clientWidth))"><figure v-for="(image,i) in images" :key="`${image}-${i}`"><img :src="image" :alt="`${label}, ${i+1}`" draggable="false" /></figure></div><nav aria-label="图片切换"><button :disabled="index===0" aria-label="上一张图片" @click="move(index-1)">‹</button><span aria-live="polite">{{ index+1 }} / {{ images.length }}</span><button :disabled="index===images.length-1" aria-label="下一张图片" @click="move(index+1)">›</button></nav></section></Teleport></template>
<style scoped>
.image-carousel { position:fixed; inset:0; z-index:3000; display:flex; flex-direction:column; background:#080c15f5; color:white; padding:env(safe-area-inset-top) 0 env(safe-area-inset-bottom); }
.close { align-self:flex-end; width:52px; min-height:52px; font-size:32px; }.carousel-track { flex:1; min-height:0; display:flex; overflow-x:auto; scroll-snap-type:x mandatory; overscroll-behavior:contain; }.carousel-track figure { flex:0 0 100%; min-width:0; margin:0; scroll-snap-align:center; display:grid; place-items:center; }.carousel-track img { width:100%; height:100%; min-height:0; object-fit:contain; } nav { display:flex; justify-content:center; align-items:center; gap:24px; min-height:64px; } nav button { width:48px; min-height:48px; font-size:28px; }button:focus-visible {outline:2px solid white;outline-offset:-4px;}
</style>
